import{M as e,O as t,f as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-DwmdDY9i.js";import{t as s}from"./plugin-vue_export-helper-BDNMzG2s.js";var c=JSON.parse(`{"path":"/01-Infrastructure/zOS/Managing%20and%20Processing%20zOS%20Data/02-mainframe-resource-sharing.html","title":"Mainframe Resource Sharing","lang":"ko-KR","frontmatter":{"description":"이 글은 IBM Z 메인프레임에서 여러 시스템이 리소스를 공유하는 방법에 대한 내용으로, PR/SM, LPAR, z/VM, 그리고 z/OS 시스템 간 리소스 공유에 대해 다룹니다.","tag":["mainframe","zos","prsm","lpar","zvm","resource-sharing"],"head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Mainframe Resource Sharing\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-01-03T09:00:08.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://docmoa.github.io/01-Infrastructure/zOS/Managing%20and%20Processing%20zOS%20Data/02-mainframe-resource-sharing.html"}],["meta",{"property":"og:site_name","content":"docmoa"}],["meta",{"property":"og:title","content":"Mainframe Resource Sharing"}],["meta",{"property":"og:description","content":"이 글은 IBM Z 메인프레임에서 여러 시스템이 리소스를 공유하는 방법에 대한 내용으로, PR/SM, LPAR, z/VM, 그리고 z/OS 시스템 간 리소스 공유에 대해 다룹니다."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"ko-KR"}],["meta",{"property":"og:updated_time","content":"2026-01-03T09:00:08.000Z"}],["meta",{"property":"article:tag","content":"resource-sharing"}],["meta",{"property":"article:tag","content":"zvm"}],["meta",{"property":"article:tag","content":"lpar"}],["meta",{"property":"article:tag","content":"prsm"}],["meta",{"property":"article:tag","content":"zos"}],["meta",{"property":"article:tag","content":"mainframe"}],["meta",{"property":"article:modified_time","content":"2026-01-03T09:00:08.000Z"}]]},"git":{"createdTime":1767430808000,"updatedTime":1767430808000,"contributors":[{"name":"Great-Stone","username":"Great-Stone","email":"hahohh@gmail.com","commits":1,"url":"https://github.com/Great-Stone"}]},"readingTime":{"minutes":92.83,"words":5570},"filePathRelative":"01-Infrastructure/zOS/Managing and Processing zOS Data/02-mainframe-resource-sharing.md","excerpt":"\\n<h2>개요</h2>\\n<p>IBM Z 메인프레임은 동시에 여러 시스템을 실행할 수 있습니다. 단일 CPC(Central Processor Complex)는 세 개의 z/OS 시스템을 실행할 수 있습니다.</p>\\n<p>여러 z/OS 시스템을 실행할 때, 이러한 시스템들은 데이터셋, 데이터베이스, 보안 정보 등과 같은 리소스를 공유하는 경우가 많습니다.</p>\\n<p>이 모듈에서는 단일 CPC에서 여러 운영 체제가 어떻게 실행되는지 탐구하고, 여러 z/OS 시스템이 리소스를 공유하는 방법을 소개합니다.</p>\\n<h2>학습 목표</h2>"}`),l={name:`02-mainframe-resource-sharing.md`};function u(s,c,l,u,d,f){let p=e(`Mermaid`);return t(),o(`div`,null,[c[0]||=n(`<h1 id="mainframe-resource-sharing" tabindex="-1"><a class="header-anchor" href="#mainframe-resource-sharing"><span>Mainframe Resource Sharing</span></a></h1><h2 id="개요" tabindex="-1"><a class="header-anchor" href="#개요"><span>개요</span></a></h2><p>IBM Z 메인프레임은 동시에 여러 시스템을 실행할 수 있습니다. 단일 CPC(Central Processor Complex)는 세 개의 z/OS 시스템을 실행할 수 있습니다.</p><p>여러 z/OS 시스템을 실행할 때, 이러한 시스템들은 데이터셋, 데이터베이스, 보안 정보 등과 같은 리소스를 공유하는 경우가 많습니다.</p><p>이 모듈에서는 단일 CPC에서 여러 운영 체제가 어떻게 실행되는지 탐구하고, 여러 z/OS 시스템이 리소스를 공유하는 방법을 소개합니다.</p><h2 id="학습-목표" tabindex="-1"><a class="header-anchor" href="#학습-목표"><span>학습 목표</span></a></h2><p>이 모듈을 완료한 후, 다음을 수행할 수 있습니다:</p><ul><li>IBM Z 메인프레임이 여러 시스템을 지원하는 방법을 설명할 수 있습니다.</li><li>z/OS 시스템이 리소스를 공유하는 방법을 설명할 수 있습니다.</li></ul><h2 id="one-cpc-multiple-systems" tabindex="-1"><a class="header-anchor" href="#one-cpc-multiple-systems"><span>One CPC, Multiple Systems</span></a></h2><h3 id="introduction" tabindex="-1"><a class="header-anchor" href="#introduction"><span>Introduction</span></a></h3><p>현재 거의 모든 IBM Z 메인프레임 사이트는 단일 운영 체제 사본만 실행하지 않습니다. 프로덕션과 개발을 위한 별도의 이미지를 가질 수 있고, 다른 비즈니스 단위를 위한 다른 시스템을 가질 수 있으며, 복원력을 위해 여러 시스템을 원할 수도 있습니다.</p><p>따라서 하나의 메인프레임 CPC는 일반적으로 여러 운영 체제 이미지를 실행합니다. 이러한 이미지는 z/OS, z/VM, z/TPF와 같은 전통적인 운영 체제이거나, Linux on IBM Z, KVM 하이퍼바이저, Secure Service Container (SSC)와 같은 최신 기술일 수 있습니다. 또한 하나 이상의 Coupling Facility를 호스팅할 수도 있습니다.</p>`,12),r(p,{code:``}),c[1]||=a(`h3`,{id:`sharing-resources`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#sharing-resources`},[a(`span`,null,`Sharing Resources`)])],-1),c[2]||=a(`p`,null,`각 운영 체제 이미지는 CPU, 메모리, I/O 연결과 같은 메인프레임 리소스가 필요합니다. 이들은 모두 CPC의 리소스를 공유해야 합니다.`,-1),r(p,{code:``}),c[3]||=a(`h3`,{id:`introducing-pr-sm`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#introducing-pr-sm`},[a(`span`,null,`Introducing PR/SM`)])],-1),c[4]||=a(`p`,null,[i(`IBM Z 메인프레임은 이러한 여러 운영 체제가 CPC 리소스를 공유할 수 있도록 하는 `),a(`strong`,null,`Processor Resource / System Manager (PR/SM)`),i(`라는 기능을 사용합니다. 다른 관점에서 보면 PR/SM은 VMWare와 Microsoft Hyper-V와 같은 하이퍼바이저입니다. PR/SM은 IBM 메인프레임에 사전 설치되어 있습니다.`)],-1),r(p,{code:``}),c[5]||=a(`p`,null,`PR/SM은 하이퍼바이저로 작동하여 물리적 하드웨어 리소스를 여러 운영 체제 이미지에 가상화하고 할당합니다.`,-1),c[6]||=a(`h3`,{id:`sharing-resources-with-pr-sm`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#sharing-resources-with-pr-sm`},[a(`span`,null,`Sharing Resources with PR/SM`)])],-1),c[7]||=a(`p`,null,`PR/SM은 CPC를 논리적 파티션(Logical Partitions, LPARs)으로 나눕니다. 각 운영 체제당 하나의 LPAR입니다. z16 및 z17 메인프레임은 최대 85개의 LPAR를 가질 수 있습니다.`,-1),c[8]||=a(`p`,null,`각 LPAR는 CPC 메모리와 CPU 리소스의 하위 집합이 할당됩니다. 예를 들어, CPC에 14개의 CPU와 500GB의 메모리가 있는 경우, 이를 세 개의 z/OS LPAR로 나눌 수 있습니다.`,-1),r(p,{code:``}),c[9]||=a(`p`,null,`위 예시에서:`,-1),c[10]||=a(`ul`,null,[a(`li`,null,`CPU: 7 (LPAR1) + 5 (LPAR2) + 2 (LPAR3) = 14 CPUs`),a(`li`,null,`Memory: 300 GB (LPAR1) + 150 GB (LPAR2) + 50 GB (LPAR3) = 500 GB memory`)],-1),c[11]||=a(`h3`,{id:`pr-sm-physical-cpu-sharing`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#pr-sm-physical-cpu-sharing`},[a(`span`,null,`PR/SM Physical CPU Sharing`)])],-1),c[12]||=a(`p`,null,`메모리와 유사한 방식으로, PR/SM은 물리적 중앙 프로세서(CPU 또는 CP)를 LPAR에 할당할 수 있습니다.`,-1),c[13]||=a(`p`,null,`이 방식의 문제점은 하나의 LPAR가 CPU를 모두 사용할 필요가 없을 때, 다른 LPAR에서 사용할 수 없다는 것입니다. PR/SM은 이를 해결하도록 구성할 수 있습니다.`,-1),r(p,{code:``}),c[14]||=a(`p`,null,`물리적 CPU 할당 방식에서는 각 LPAR가 전용 CPU를 가지지만, CPU가 유휴 상태일 때 다른 LPAR에서 사용할 수 없어 리소스 낭비가 발생할 수 있습니다.`,-1),c[15]||=a(`h3`,{id:`pr-sm-logical-cpu-sharing`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#pr-sm-logical-cpu-sharing`},[a(`span`,null,`PR/SM Logical CPU Sharing`)])],-1),c[16]||=a(`p`,null,`PR/SM은 메모리를 LPAR 간에 나눕니다. 각 LPAR는 자체 메모리 영역을 가집니다.`,-1),c[17]||=a(`p`,null,`PR/SM은 CPU를 더 정교한 방식으로 공유합니다. 각 물리적 프로세서를 LPAR에 할당하는 대신, PR/SM은 CPU를 공유하여 하나의 LPAR가 필요하지 않으면 다른 LPAR가 사용할 수 있도록 합니다. 일부 LPAR가 다른 LPAR보다 더 많은 CPU를 받도록 설정할 수도 있습니다.`,-1),r(p,{code:``}),c[18]||=a(`h4`,{id:`논리적-cpu-공유의-작동-방식`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#논리적-cpu-공유의-작동-방식`},[a(`span`,null,`논리적 CPU 공유의 작동 방식`)])],-1),c[19]||=a(`p`,null,`이 예시에서 각 LPAR는 하나의 논리적 CPU를 가지며, CPC에는 세 개의 논리적 CPU가 있습니다. 각 LPAR는 하나의 CPU에 대한 독점적 액세스를 가지고 있다고 믿습니다.`,-1),r(p,{code:``}),c[20]||=a(`h4`,{id:`cpu-공유-시나리오`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#cpu-공유-시나리오`},[a(`span`,null,`CPU 공유 시나리오`)])],-1),c[21]||=a(`p`,null,`하나의 LPAR가 CPU를 사용할 필요가 없으면 다른 LPAR에서 사용할 수 있습니다.`,-1),r(p,{code:``}),c[22]||=a(`h4`,{id:`대기-시나리오`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#대기-시나리오`},[a(`span`,null,`대기 시나리오`)])],-1),c[23]||=a(`p`,null,`LPAR3이 CPU를 사용해야 하지만 LPAR2가 사용 중인 경우, LPAR3은 LPAR2가 CPU 사용을 마치거나 PR/SM이 LPAR3의 차례로 판단할 때까지 대기합니다.`,-1),r(p,{code:``}),c[24]||=a(`h4`,{id:`바쁜-시스템에서의-cpu-공유`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#바쁜-시스템에서의-cpu-공유`},[a(`span`,null,`바쁜 시스템에서의 CPU 공유`)])],-1),c[25]||=a(`p`,null,`바쁜 시스템에서는 모든 LPAR가 CPU 차례를 기다려야 합니다. PR/SM은 LPAR 간에 CPU를 최대한 균등하게 공유하려고 합니다.`,-1),r(p,{code:``}),c[26]||=a(`h4`,{id:`가중치를-사용한-cpu-공유`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#가중치를-사용한-cpu-공유`},[a(`span`,null,`가중치를 사용한 CPU 공유`)])],-1),c[27]||=a(`p`,null,`PR/SM을 사용하면 각 LPAR에 가중치를 할당할 수 있습니다. 가중치가 높은 LPAR는 가중치가 낮은 LPAR보다 대기 시간이 짧습니다.`,-1),r(p,{code:``}),c[28]||=a(`h4`,{id:`가중치와-워크로드`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#가중치와-워크로드`},[a(`span`,null,`가중치와 워크로드`)])],-1),c[29]||=a(`p`,null,`LPAR가 공유 프로세서를 기다리는 것은 다른 LPAR가 사용 중일 때만입니다. 다른 LPAR가 CPU를 사용하지 않으면, 가중치가 낮은 LPAR도 전혀 기다릴 필요가 없습니다.`,-1),r(p,{code:``}),c[30]||=n(`<h3 id="pr-sm-and-cpu-types" tabindex="-1"><a class="header-anchor" href="#pr-sm-and-cpu-types"><span>PR/SM and CPU Types</span></a></h3><p>PR/SM 프로세서 공유는 메인프레임의 다양한 유형의 프로세서에 대해 작동합니다. 여기에는 다음 유형의 CPU가 포함됩니다:</p><ul><li><strong>General purpose (GP) processors</strong> (일반 목적 프로세서), 때로는 중앙 프로세서 또는 CP라고도 함</li><li><strong>zIIP</strong> - GP에서 작업 오프로딩</li><li><strong>IFL</strong> - Linux on IBM Z</li><li><strong>ICF</strong> - Coupling Facility용</li></ul>`,3),r(p,{code:``}),c[31]||=n(`<h4 id="cpu-유형별-용도" tabindex="-1"><a class="header-anchor" href="#cpu-유형별-용도"><span>CPU 유형별 용도</span></a></h4><ul><li><strong>GP (General Purpose)</strong>: z/OS 시스템의 일반적인 처리 작업</li><li><strong>zIIP</strong>: z/OS에서 특정 작업(예: DB2, XML 처리)을 GP에서 오프로딩</li><li><strong>IFL</strong>: Linux on IBM Z 전용 프로세서</li><li><strong>ICF</strong>: Coupling Facility 전용 프로세서</li></ul><h3 id="system-recovery-boost" tabindex="-1"><a class="header-anchor" href="#system-recovery-boost"><span>System Recovery Boost</span></a></h3><p>z15 메인프레임 출시 이후, <strong>System Recovery Boost</strong> 기능이 선택적 기능으로 추가되어 셧다운 기간 동안 또는 시스템이 IPL되는 동안 임시 zIIP 용량을 활용하여 복구 시간을 단축하고 다운타임을 최소화할 수 있습니다. 이 기능은 z16 및 z17 메인프레임에서도 계속 지원됩니다.</p><p>이 추가 zIIP 용량은 PR/SM 관리 제어에 따라 LPAR 간에 공유됩니다. 운영 체제가 부스트 기간 동안 이를 사용하려면 LPAR가 PR/SM 이미지 프로필에 미리 정의된 예약된 논리적 zIIP 용량으로 구성되어 있어야 합니다.</p>`,5),r(p,{code:``}),c[32]||=n(`<h4 id="system-recovery-boost의-특징" tabindex="-1"><a class="header-anchor" href="#system-recovery-boost의-특징"><span>System Recovery Boost의 특징</span></a></h4><ul><li><strong>목적</strong>: 복구 시간 단축 및 다운타임 최소화</li><li><strong>활성화 시기</strong>: 셧다운 기간 또는 시스템 IPL 중</li><li><strong>리소스</strong>: 임시 zIIP 용량</li><li><strong>요구사항</strong>: LPAR에 예약된 논리적 zIIP 용량이 PR/SM 이미지 프로필에 정의되어 있어야 함</li></ul><h3 id="channel-sharing" tabindex="-1"><a class="header-anchor" href="#channel-sharing"><span>Channel Sharing</span></a></h3><p>PR/SM LPAR는 <strong>Multiple Image Facility (MIF)</strong>를 사용하여 채널을 공유할 수 있습니다. 이는 외부 장치에 연결된 물리적 채널 수를 줄입니다.</p><p>각 LPAR는 각 채널에 대한 독점적 액세스를 가지고 있는 것처럼 작동합니다. 그러나 PR/SM은 이러한 시스템이 각 채널을 공유하도록 처리합니다.</p>`,5),r(p,{code:``}),c[33]||=n(`<h4 id="channel-sharing의-이점" tabindex="-1"><a class="header-anchor" href="#channel-sharing의-이점"><span>Channel Sharing의 이점</span></a></h4><ul><li><strong>물리적 채널 수 감소</strong>: 여러 LPAR가 동일한 물리적 채널을 공유</li><li><strong>비용 절감</strong>: 필요한 물리적 채널 하드웨어 감소</li><li><strong>투명성</strong>: 각 LPAR는 독점적 액세스를 가지고 있다고 인식</li></ul><h3 id="open-system-adapter-sharing" tabindex="-1"><a class="header-anchor" href="#open-system-adapter-sharing"><span>Open System Adapter Sharing</span></a></h3><p>채널과 마찬가지로, <strong>Open System Adapters (OSAs)</strong>는 LPAR 간에 공유될 수 있습니다. 다시 말해, 각 LPAR는 OSA에 대한 독점적 액세스를 가지고 있다고 믿습니다.</p>`,4),r(p,{code:``}),c[34]||=n(`<h4 id="osa-sharing의-특징" tabindex="-1"><a class="header-anchor" href="#osa-sharing의-특징"><span>OSA Sharing의 특징</span></a></h4><ul><li><strong>네트워크 연결 공유</strong>: 여러 LPAR가 동일한 OSA를 통해 네트워크에 접근</li><li><strong>투명성</strong>: 각 LPAR는 OSA에 대한 독점적 액세스를 가지고 있다고 인식</li><li><strong>효율성</strong>: 물리적 OSA 하드웨어 수 감소</li></ul><h3 id="introducing-z-vm" tabindex="-1"><a class="header-anchor" href="#introducing-z-vm"><span>Introducing z/VM</span></a></h3><p><strong>z/VM</strong>은 하이퍼바이저로 사용할 수 있는 IBM 운영 체제입니다. 다른 운영 체제와 마찬가지로 PR/SM 아래의 LPAR에서 작동합니다. 그러나 z/VM은 게스트 또는 다른 운영 체제를 호스팅할 수 있습니다.</p><p>많은 사용자가 z/VM을 사용하여 Linux on IBM Z 파티션을 호스팅합니다.</p><p>z/VM은 게스트 간에 CPU, 메모리, 채널, OSA 공유를 포함하여 PR/SM과 동일한 많은 기능을 제공합니다.</p>`,6),r(p,{code:``}),c[35]||=n(`<h4 id="z-vm의-특징" tabindex="-1"><a class="header-anchor" href="#z-vm의-특징"><span>z/VM의 특징</span></a></h4><ul><li><strong>하이퍼바이저 기능</strong>: PR/SM 아래의 LPAR에서 실행되면서 다른 운영 체제를 호스팅</li><li><strong>게스트 운영 체제 지원</strong>: z/OS, Linux on IBM Z 등</li><li><strong>리소스 공유</strong>: CPU, 메모리, 채널, OSA를 게스트 간에 공유</li><li><strong>주요 용도</strong>: Linux on IBM Z 파티션 호스팅</li></ul><h4 id="pr-sm-vs-z-vm" tabindex="-1"><a class="header-anchor" href="#pr-sm-vs-z-vm"><span>PR/SM vs z/VM</span></a></h4><table><thead><tr><th>특징</th><th>PR/SM</th><th>z/VM</th></tr></thead><tbody><tr><td><strong>위치</strong></td><td>펌웨어/하이퍼바이저</td><td>운영 체제</td></tr><tr><td><strong>설치</strong></td><td>메인프레임에 사전 설치</td><td>LPAR에 설치</td></tr><tr><td><strong>용도</strong></td><td>LPAR 관리 및 리소스 공유</td><td>게스트 운영 체제 호스팅</td></tr><tr><td><strong>게스트 지원</strong></td><td>없음 (LPAR 수준)</td><td>있음 (게스트 운영 체제)</td></tr></tbody></table><h3 id="summary" tabindex="-1"><a class="header-anchor" href="#summary"><span>Summary</span></a></h3><p>이 섹션에서는 하나의 CPC가 동시에 여러 운영 체제 이미지를 실행할 수 있음을 확인했습니다. 메인프레임 기능인 PR/SM은 각 LPAR가 CPU, 메모리, 채널, OSA 연결을 포함한 리소스를 공유할 수 있도록 합니다.</p><h4 id="주요-학습-내용" tabindex="-1"><a class="header-anchor" href="#주요-학습-내용"><span>주요 학습 내용</span></a></h4><ol><li><p><strong>하나의 CPC, 여러 시스템</strong></p><ul><li>하나의 CPC에서 여러 운영 체제 이미지 실행 가능</li><li>z/OS, z/VM, z/TPF, Linux on IBM Z, KVM, Secure Service Container 등 지원</li></ul></li><li><p><strong>PR/SM (Processor Resource / System Manager)</strong></p><ul><li>IBM Z 메인프레임에 사전 설치된 하이퍼바이저</li><li>CPC를 논리적 파티션(LPAR)으로 분할</li><li>z16 및 z17 메인프레임은 최대 85개의 LPAR 지원</li><li>z17은 Telum II 프로세서와 IBM Z 통합 AI 가속기를 지원</li></ul></li><li><p><strong>리소스 공유</strong></p><ul><li><strong>메모리</strong>: LPAR 간에 분할, 각 LPAR는 자체 메모리 영역 보유</li><li><strong>CPU</strong>: 물리적 또는 논리적 CPU 공유 <ul><li>물리적 CPU 공유: 각 LPAR에 전용 CPU 할당</li><li>논리적 CPU 공유: 여러 LPAR가 물리적 CPU를 공유, 가중치 기반 할당 가능</li></ul></li><li><strong>채널</strong>: Multiple Image Facility (MIF)를 통한 채널 공유</li><li><strong>OSA</strong>: Open System Adapter 공유</li></ul></li><li><p><strong>CPU 유형</strong></p><ul><li>GP (General Purpose): 일반 목적 프로세서</li><li>zIIP: 작업 오프로딩용</li><li>IFL: Linux on IBM Z용</li><li>ICF: Coupling Facility용</li></ul></li><li><p><strong>System Recovery Boost</strong></p><ul><li>z15 이후 추가된 기능</li><li>복구 시간 단축을 위한 임시 zIIP 용량 제공</li></ul></li><li><p><strong>z/VM</strong></p><ul><li>하이퍼바이저로 사용 가능한 운영 체제</li><li>PR/SM 아래의 LPAR에서 실행되면서 게스트 운영 체제 호스팅</li><li>주로 Linux on IBM Z 파티션 호스팅에 사용</li></ul></li></ol><div class="hint-container tip"><p class="hint-container-title">One CPC, Multiple Systems 요약</p><p>하나의 CPC는 여러 운영 체제 이미지를 동시에 실행할 수 있습니다. PR/SM은 이러한 시스템이 CPU, 메모리, 채널, OSA 연결과 같은 리소스를 공유할 수 있도록 합니다. z16 및 z17 메인프레임은 최대 85개의 LPAR를 지원하며, z17은 Telum II 프로세서와 IBM Z 통합 AI 가속기를 통해 향상된 AI 기능을 제공합니다. 다음 섹션에서는 다른 리소스 공유가 가능한 방법을 탐구합니다.</p></div><h2 id="resource-sharing-between-z-os" tabindex="-1"><a class="header-anchor" href="#resource-sharing-between-z-os"><span>Resource Sharing Between z/OS</span></a></h2><h3 id="introduction-1" tabindex="-1"><a class="header-anchor" href="#introduction-1"><span>Introduction</span></a></h3><p>많은 메인프레임 사용자는 하나 이상의 z/OS 시스템을 실행합니다. 이러한 시스템들은 같은 CPC에 있을 수도 있고, 서로 다른 CPC에 있을 수도 있습니다. 이를 통해 사용 가능한 처리 능력을 증가시키고, 한 시스템이 실패할 경우 복원력을 제공할 수 있습니다.</p><p>종종 이러한 z/OS 시스템들은 CPC 메모리, 채널, CPU 이외의 다른 리소스를 공유해야 합니다.</p>`,13),r(p,{code:`eJyNkEsPgjAMx+9+CjKvGicXHzEmPg6a+IrGi4uHMYoQF0bGCNFP74ABM/FgD13763/r2oCLnIVUKmd37jjabsfLkKD3QB/oXhO3Iq4hpUsz7yFpEjpnSEUmGaQEXfRL4LfE6As7gMqFfBJkAqu0Ol0J0s5Ca6qoR1MgqI6s4iJJeMSoikSse9qZJdpQ6ef6NwRtl/smMwKI/XaQYmJn1u/Py0lbVJBmkmYTP3C1DvXiUF0MIs6n3fGIAXg9JriQ0y7G+Fvm/iFr2hjtBANMsK39APQNfTA=`}),c[36]||=a(`h3`,{id:`sysplex`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#sysplex`},[a(`span`,null,`Sysplex`)])],-1),c[37]||=a(`p`,null,[i(`리소스를 공유해야 하는 여러 z/OS 시스템은 `),a(`strong`,null,`IBM sysplex 기술`),i(`을 사용합니다. 이 클러스터링 기술은 채널을 사용하여 최대 32개의 z/OS 이미지를 연결하며, 일반적으로 통신을 위해 coupling facility를 사용합니다.`)],-1),c[38]||=a(`p`,null,`일부 사이트는 여러 sysplex를 가질 수 있습니다. 예를 들어, 프로덕션용 sysplex 하나와 개발용 sysplex 하나를 가질 수 있습니다.`,-1),r(p,{code:``}),c[39]||=n(`<h4 id="sysplex의-특징" tabindex="-1"><a class="header-anchor" href="#sysplex의-특징"><span>Sysplex의 특징</span></a></h4><ul><li><strong>최대 32개 z/OS 이미지 연결</strong>: 채널을 사용하여 연결</li><li><strong>Coupling Facility 사용</strong>: 일반적으로 통신을 위해 coupling facility 사용</li><li><strong>여러 Sysplex 구성 가능</strong>: 프로덕션, 개발 등 목적에 따라 분리 가능</li><li><strong>서로 다른 CPC에 위치 가능</strong>: 같은 CPC 또는 다른 CPC에 있을 수 있음</li></ul><h3 id="xcf" tabindex="-1"><a class="header-anchor" href="#xcf"><span>XCF</span></a></h3><p><strong>XCF (Cross-System Coupling Facility)</strong>는 sysplex 내의 태스크 간 통신을 제공합니다.</p><p>XCF는 z/OS 시스템의 태스크가 다른 태스크와 통신할 수 있도록 서비스를 제공합니다. 이 통신은 같은 z/OS 시스템 내에서 발생할 수도 있고, 같은 sysplex 내의 다른 z/OS 시스템에서 발생할 수도 있습니다.</p><p>많은 시스템이 이 통신에 의존하여 공유 및 기타 sysplex 서비스를 제공합니다.</p>`,6),r(p,{code:``}),c[40]||=n(`<h4 id="xcf의-기능" tabindex="-1"><a class="header-anchor" href="#xcf의-기능"><span>XCF의 기능</span></a></h4><ul><li><strong>태스크 간 통신</strong>: 같은 z/OS 시스템 내 또는 다른 z/OS 시스템 간</li><li><strong>Sysplex 서비스 지원</strong>: 공유 및 기타 sysplex 서비스 제공</li><li><strong>투명한 통신</strong>: 태스크는 통신이 같은 시스템 내에서 발생하는지 다른 시스템에서 발생하는지 알 필요 없음</li></ul><h3 id="time" tabindex="-1"><a class="header-anchor" href="#time"><span>Time</span></a></h3><p>Sysplex에서는 각 z/OS 시스템이 동일한 시간을 가져야 합니다. ZOS1이 12:00라고 생각하고, ZOS2가 12:02라고 생각하고, ZOS3이 11:58이라고 생각하면, 리소스 공유, 공통 로그 표시 및 기타 내부 기능에 문제가 발생할 수 있습니다.</p><p>이를 해결하기 위해 IBM Z 메인프레임은 채널 링크를 통해 통신하고 올바른 시간에 동의합니다. 이것은 <strong>Server Time Protocol (STP)</strong>라는 프로토콜을 사용하여 수행됩니다.</p><p>STP는 IBM Z 메인프레임의 하드웨어 클록을 동기화합니다. 또한 외부 클록과도 동기화할 수 있어 메인프레임이 비메인프레임 서버와 시간을 조정할 수 있습니다.</p>`,6),r(p,{code:``}),c[41]||=n(`<h4 id="stp-server-time-protocol-의-특징" tabindex="-1"><a class="header-anchor" href="#stp-server-time-protocol-의-특징"><span>STP (Server Time Protocol)의 특징</span></a></h4><ul><li><strong>하드웨어 클록 동기화</strong>: IBM Z 메인프레임의 하드웨어 클록을 동기화</li><li><strong>외부 클록 지원</strong>: 외부 시간 서버와 동기화 가능</li><li><strong>채널 링크 사용</strong>: 채널 링크를 통해 통신</li><li><strong>비메인프레임 서버와 조정</strong>: 비메인프레임 서버와도 시간 조정 가능</li></ul><h3 id="coupling-facility" tabindex="-1"><a class="header-anchor" href="#coupling-facility"><span>Coupling Facility</span></a></h3><p><strong>기본 Sysplex (Basic Sysplex)</strong>는 여러 z/OS 시스템이 채널만 사용하여 통신하는 경우입니다.</p><p>대부분의 sysplex는 하나 이상의 <strong>Coupling Facility</strong>를 가지며, z/OS 및 관련 서브시스템이 리소스 공유를 위한 공통 메모리로 사용합니다. 이러한 sysplex를 <strong>Parallel Sysplex</strong>라고 합니다.</p><p>이러한 coupling facility는 다양한 서브시스템에서 다양한 방식으로 사용되어 리소스 공유를 지원할 수 있습니다.</p>`,6),r(p,{code:``}),c[42]||=n(`<h4 id="basic-sysplex-vs-parallel-sysplex" tabindex="-1"><a class="header-anchor" href="#basic-sysplex-vs-parallel-sysplex"><span>Basic Sysplex vs Parallel Sysplex</span></a></h4><table><thead><tr><th>특징</th><th>Basic Sysplex</th><th>Parallel Sysplex</th></tr></thead><tbody><tr><td><strong>통신 방법</strong></td><td>채널만 사용</td><td>채널 + Coupling Facility</td></tr><tr><td><strong>Coupling Facility</strong></td><td>없음</td><td>하나 이상 사용</td></tr><tr><td><strong>공유 메모리</strong></td><td>없음</td><td>Coupling Facility를 통한 공유 메모리</td></tr><tr><td><strong>리소스 공유</strong></td><td>제한적</td><td>향상된 리소스 공유</td></tr></tbody></table><h4 id="coupling-facility의-용도" tabindex="-1"><a class="header-anchor" href="#coupling-facility의-용도"><span>Coupling Facility의 용도</span></a></h4><ul><li><strong>공통 메모리</strong>: z/OS 및 관련 서브시스템이 리소스 공유를 위한 공통 메모리로 사용</li><li><strong>다양한 서브시스템 지원</strong>: 다양한 서브시스템에서 다양한 방식으로 사용</li><li><strong>리소스 공유 지원</strong>: 리소스 공유를 지원하는 핵심 구성 요소</li></ul><h3 id="serialization" tabindex="-1"><a class="header-anchor" href="#serialization"><span>Serialization</span></a></h3><p>XCF, STP, coupling facility를 통해 z/OS는 리소스를 공유하거나 sysplex 주변에서 통신해야 하는 태스크를 위한 추가 서비스를 제공할 수 있습니다.</p><p>가장 자주 사용되는 것 중 하나는 <strong>enqueue (ENQ)</strong>입니다. 태스크가 리소스를 직렬화하는 데 사용됩니다. Sysplex에서 enqueue는 모든 z/OS 시스템에서 볼 수 있습니다.</p><h4 id="enqueue-enq-의-개념" tabindex="-1"><a class="header-anchor" href="#enqueue-enq-의-개념"><span>Enqueue (ENQ)의 개념</span></a></h4><p>태스크는 enqueue를 요청할 수 있습니다. 이 enqueue는 두 개의 이름을 가집니다:</p><ul><li><strong>QName (Queue Name)</strong>: 주요 이름 (Major name)</li><li><strong>RName (Resource Name)</strong>: 부 이름 (Minor name)</li></ul>`,10),r(p,{code:``}),c[43]||=a(`h4`,{id:`enqueue의-작동-방식`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#enqueue의-작동-방식`},[a(`span`,null,`Enqueue의 작동 방식`)])],-1),c[44]||=a(`p`,null,`Enqueue는 실제 리소스와의 연결이 없습니다. z/OS에게는 단순히 QName과 RName이며, 한 번에 하나의 태스크만 보유할 수 있습니다.`,-1),c[45]||=a(`h5`,{id:`_1-enqueue-획득`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#_1-enqueue-획득`},[a(`span`,null,`1. Enqueue 획득`)])],-1),c[46]||=a(`p`,null,`다른 태스크(Task2)가 이미 enqueue를 획득한 경우, enqueue 요청이 실패합니다. 태스크(Task1)는 대기하거나 다른 처리를 수행할 수 있습니다.`,-1),r(p,{code:``}),c[47]||=a(`h5`,{id:`_2-enqueue-해제`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#_2-enqueue-해제`},[a(`span`,null,`2. Enqueue 해제`)])],-1),c[48]||=a(`p`,null,`태스크가 더 이상 enqueue가 필요하지 않으면 해제합니다. 다른 태스크가 이제 enqueue를 획득할 수 있습니다.`,-1),r(p,{code:``}),c[49]||=a(`h4`,{id:`enqueue-사용-예시`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#enqueue-사용-예시`},[a(`span`,null,`Enqueue 사용 예시`)])],-1),c[50]||=a(`h5`,{id:`단일-z-os-시스템-내에서`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#단일-z-os-시스템-내에서`},[a(`span`,null,`단일 z/OS 시스템 내에서`)])],-1),c[51]||=a(`p`,null,`Enqueue는 하나의 z/OS 시스템 내에서 리소스를 직렬화하는 데 사용될 수 있습니다.`,-1),r(p,{code:`eJxdUMFuwjAMve8rrHJdR+CyUU1IHHrbOlF2GtohDWZUCwnEiRB8Pa6LRIUPfvLL83tJttafzE6HCB/1E3BRav6CPuzg52s1WWeXMUP2K0ddfWv6Z1rggZ729PRGo9sISiur5Trj9t6E8XxZLT7LAupyNZG57ucF121XmmRAns+77Ttd+Yh8g9IdEyYkMNpBg5AINxA9EIZW2/aCYh2QfAqGZa0D7xC69wCdKeJ+mMUJkL9wlLjfeYpni/IVsG2tLUZvrwaxeTbe+lCMlFIDWWfSq2YKcaaGqiu65GGb`}),c[52]||=a(`h5`,{id:`여러-z-os-시스템-간에서`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#여러-z-os-시스템-간에서`},[a(`span`,null,`여러 z/OS 시스템 간에서`)])],-1),c[53]||=a(`p`,null,`Enqueue는 sysplex 내의 여러 z/OS 시스템 간에 리소스를 직렬화하는 데도 사용될 수 있으며, 서로 다른 CPC에 있어도 가능합니다.`,-1),r(p,{code:``}),c[54]||=a(`h4`,{id:`z-os의-enqueue-사용`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#z-os의-enqueue-사용`},[a(`span`,null,`z/OS의 Enqueue 사용`)])],-1),c[55]||=a(`p`,null,[i(`z/OS 자체도 enqueue를 사용합니다. 예를 들어, QName `),a(`strong`,null,`SYSDSN`),i(`은 데이터셋에 대한 액세스를 직렬화하는 데 사용됩니다. RName은 데이터셋 이름입니다.`)],-1),r(p,{code:``}),c[56]||=a(`h3`,{id:`z-os-sharing-facilities`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#z-os-sharing-facilities`},[a(`span`,null,`z/OS Sharing Facilities`)])],-1),c[57]||=a(`p`,null,`z/OS 구성 요소는 STP, coupling facility, XCF, ENQ를 기반으로 더 많은 공유 옵션과 기능을 제공합니다. 여기서는 그 중 일부를 나열합니다.`,-1),c[58]||=a(`h4`,{id:`data-sets`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#data-sets`},[a(`span`,null,`Data Sets`)])],-1),c[59]||=a(`p`,null,`데이터셋은 서로 다른 z/OS 시스템의 태스크 간에 공유될 수 있습니다. z/OS는 이러한 데이터셋에 대한 액세스를 직렬화하기 위해 enqueue를 사용합니다.`,-1),c[60]||=a(`p`,null,`데이터셋은 한 번에 하나의 태스크만 액세스할 수 있도록 정의되거나, 동시에 여러 태스크가 액세스할 수 있도록 정의될 수 있습니다. 예를 들어, 데이터셋은 한 번에 하나의 태스크만 업데이트할 수 있지만, 동시에 여러 태스크가 읽을 수 있도록 정의될 수 있습니다.`,-1),r(p,{code:``}),c[61]||=a(`h4`,{id:`jes-job-entry-subsystem`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#jes-job-entry-subsystem`},[a(`span`,null,`JES (Job Entry Subsystem)`)])],-1),c[62]||=a(`p`,null,`JES 서브시스템은 여러 z/OS 시스템에 의해 공유될 수 있습니다. JES spool은 서로 다른 서브시스템의 태스크에 의해 읽고 쓸 수 있습니다. 한 z/OS 시스템에서 제출된 배치 작업이 다른 시스템에서 자동으로 실행될 수 있습니다.`,-1),r(p,{code:``}),c[63]||=a(`h4`,{id:`vsam-records`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#vsam-records`},[a(`span`,null,`VSAM Records`)])],-1),c[64]||=a(`p`,null,[i(`데이터셋은 공유될 수 있지만, 일반적으로 한 번에 하나의 태스크만 데이터셋을 업데이트할 수 있습니다. 그러나 `),a(`strong`,null,`VSAM Record-Level Sharing (RLS)`),i(`을 사용하면 여러 태스크가 동시에 VSAM 데이터셋을 업데이트할 수 있습니다.`)],-1),c[65]||=a(`p`,null,`RLS는 데이터셋 레벨이 아닌 레코드 레벨에서 직렬화를 수행합니다. 따라서 한 태스크가 하나의 레코드를 업데이트하는 동안 두 번째 태스크가 다른 레코드를 동시에 업데이트할 수 있습니다.`,-1),r(p,{code:``}),c[66]||=a(`h4`,{id:`security`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#security`},[a(`span`,null,`Security`)])],-1),c[67]||=a(`p`,null,`RACF 및 Broadcom의 ACF2와 같은 z/OS 보안 소프트웨어는 z/OS 시스템 간에 공유될 수 있습니다. Sysplex의 모든 시스템이 하나의 보안 데이터베이스를 공유하므로 동일한 보안 규칙을 가집니다.`,-1),c[68]||=a(`p`,null,`한 z/OS 시스템에서 규칙이 변경되거나 새 사용자가 추가되면, 해당 변경 사항은 다른 모든 z/OS 시스템에서도 볼 수 있습니다.`,-1),r(p,{code:``}),c[69]||=a(`h4`,{id:`logs`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#logs`},[a(`span`,null,`Logs`)])],-1),c[70]||=a(`p`,null,`많은 시스템 로그 활동이 시작될 수 있습니다. 예를 들어, z/OS는 Operlog에 오류 메시지 및 기타 작업을 기록합니다. 마찬가지로 WebSphere Application Server는 로그에 오류 메시지를 기록합니다.`,-1),c[71]||=a(`p`,null,`z/OS는 이러한 로그에 대한 logstream을 제공하며, 이는 서로 다른 z/OS 시스템의 여러 태스크에 의해 공유될 수 있습니다. 따라서 두 개의 WebSphere Application Server 태스크가 서로 다른 z/OS 시스템에 있어도 동일한 logstream에 쓸 수 있습니다. 이는 문제 해결을 더 쉽게 만들 수 있습니다.`,-1),r(p,{code:``}),c[72]||=a(`h4`,{id:`tape-drive`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#tape-drive`},[a(`span`,null,`Tape Drive`)])],-1),c[73]||=a(`p`,null,`테이프 드라이브는 여러 z/OS 태스크에 의해 공유될 수 있습니다. 태스크가 테이프 드라이브가 필요할 때, 작업이 완료될 때까지 드라이브에 대한 독점적 액세스가 제공됩니다. 그런 다음 테이프 드라이브는 다른 태스크가 사용할 수 있게 됩니다.`,-1),r(p,{code:``}),c[74]||=a(`h3`,{id:`other-sharing-facilities`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#other-sharing-facilities`},[a(`span`,null,`Other Sharing Facilities`)])],-1),c[75]||=a(`p`,null,`z/OS만이 공유를 위해 sysplex 기능을 사용하는 것은 아닙니다. 데이터베이스 서버, 트랜잭션 관리자, 메시징 시스템을 포함한 다른 시스템도 sysplex 기능을 사용합니다.`,-1),c[76]||=a(`h4`,{id:`cics`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#cics`},[a(`span`,null,`CICS`)])],-1),c[77]||=a(`p`,null,`CICS 영역은 리소스를 공유할 수 있습니다. 이미 VSAM RLS를 사용하여 서로 다른 태스크가 VSAM 데이터셋을 공유하는 방법을 살펴봤습니다. CICS는 또한 임시 저장소 큐, coupling facility 데이터셋이라고 하는 데이터 공간, named counter라고 하는 카운터를 공유하는 기능을 제공합니다.`,-1),c[78]||=a(`p`,null,`CICSPlex에서 CICS 영역은 들어오는 워크로드를 공유할 수도 있으며, 들어오는 작업을 그들 사이에서 나눕니다.`,-1),r(p,{code:``}),c[79]||=a(`h4`,{id:`db2`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#db2`},[a(`span`,null,`Db2`)])],-1),c[80]||=a(`p`,null,[i(`Db2 리소스는 여러 Db2 서브시스템에 의해 공유될 수 있습니다. 이를 통해 sysplex의 서로 다른 z/OS 시스템에 있는 태스크가 Db2 데이터를 공유할 수 있습니다. 이것은 `),a(`strong`,null,`Db2 data sharing group`),i(`을 사용하여 수행됩니다.`)],-1),r(p,{code:``}),c[81]||=a(`h4`,{id:`ims-tm-transaction-manager`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#ims-tm-transaction-manager`},[a(`span`,null,`IMS TM (Transaction Manager)`)])],-1),c[82]||=a(`p`,null,`IMS Transaction Manager (IMS TM) 큐는 서로 다른 IMS 서브시스템 간에 공유될 수 있습니다. 이를 통해 여러 IMS 서브시스템이 워크로드를 공유할 수 있습니다.`,-1),r(p,{code:``}),c[83]||=a(`h4`,{id:`ims-db-database`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#ims-db-database`},[a(`span`,null,`IMS DB (Database)`)])],-1),c[84]||=a(`p`,null,`IMS 데이터베이스는 같은 또는 서로 다른 z/OS 시스템의 IMS 서브시스템 간에 공유될 수 있습니다.`,-1),r(p,{code:``}),c[85]||=a(`h4`,{id:`ibm-mq`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#ibm-mq`},[a(`span`,null,`IBM MQ`)])],-1),c[86]||=a(`p`,null,`IBM MQ 큐는 같은 또는 서로 다른 z/OS 시스템의 MQ 큐 관리자 간에 공유될 수 있습니다. 이를 통해 여러 태스크가 동시에 같은 큐에서 가져오거나 같은 큐에 넣을 수 있습니다.`,-1),r(p,{code:``}),c[87]||=n(`<h3 id="vtam-logical-unit-sharing" tabindex="-1"><a class="header-anchor" href="#vtam-logical-unit-sharing"><span>VTAM Logical Unit Sharing</span></a></h3><p>z/OS 태스크는 네트워크 리소스도 공유할 수 있습니다. 예를 들어, <strong>VTAM Logical Units (LUs)</strong>를 공유할 수 있습니다.</p><h4 id="vtam-lu의-개념" tabindex="-1"><a class="header-anchor" href="#vtam-lu의-개념"><span>VTAM LU의 개념</span></a></h4><p>3270 사용자가 CICS 또는 TSO와 같은 애플리케이션에 로그온할 때, 애플리케이션의 VTAM logical unit (LU)에 로그온합니다. 이것은 때때로 <strong>Application ID</strong> 또는 줄여서 <strong>APPLID</strong>라고 불립니다.</p>`,4),r(p,{code:``}),c[88]||=a(`h4`,{id:`vtam-generic-resource`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#vtam-generic-resource`},[a(`span`,null,`VTAM Generic Resource`)])],-1),c[89]||=a(`p`,null,[i(`두 애플리케이션이 APPLID를 공유할 수 있습니다. 이것을 `),a(`strong`,null,`VTAM generic resource`),i(`라고 합니다.`)],-1),r(p,{code:``}),c[90]||=a(`h4`,{id:`자동-라우팅`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#자동-라우팅`},[a(`span`,null,`자동 라우팅`)])],-1),c[91]||=a(`p`,null,`사용자는 어떤 애플리케이션에 로그온하는지 알 필요가 없습니다. 이것은 VTAM에 의해 결정됩니다.`,-1),r(p,{code:``}),c[92]||=a(`h4`,{id:`고가용성`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#고가용성`},[a(`span`,null,`고가용성`)])],-1),c[93]||=a(`p`,null,`한 애플리케이션이 사용할 수 없으면, 사용자는 자동으로 작동 중인 애플리케이션으로 라우팅됩니다.`,-1),r(p,{code:``}),c[94]||=a(`h3`,{id:`share-tcp-ip`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#share-tcp-ip`},[a(`span`,null,`Share TCP/IP`)])],-1),c[95]||=a(`p`,null,`z/OS 애플리케이션은 VTAM generic resource와 유사한 방식으로 TCP/IP 포트를 공유할 수 있습니다.`,-1),c[96]||=a(`h4`,{id:`tcp-ip-포트-리스닝`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#tcp-ip-포트-리스닝`},[a(`span`,null,`TCP/IP 포트 리스닝`)])],-1),c[97]||=a(`p`,null,`들어오는 TCP/IP 메시지를 서비스하는 태스크나 애플리케이션은 포트에서 리스닝합니다.`,-1),r(p,{code:``}),c[98]||=a(`h4`,{id:`외부-태스크-연결`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#외부-태스크-연결`},[a(`span`,null,`외부 태스크 연결`)])],-1),c[99]||=a(`p`,null,`애플리케이션에 메시지를 보내는 외부 태스크는 서버의 TCP/IP 주소와 포트 번호를 지정합니다.`,-1),r(p,{code:``}),c[100]||=a(`p`,null,`z/OS의 TCP/IP는 들어오는 트래픽을 해당 포트에서 리스닝하는 애플리케이션으로 전송합니다.`,-1),c[101]||=a(`h4`,{id:`애플리케이션-간-포트-공유`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#애플리케이션-간-포트-공유`},[a(`span`,null,`애플리케이션 간 포트 공유`)])],-1),c[102]||=a(`p`,null,`z/OS 시스템에서 동일한 TCP/IP 서비스를 사용하는 두 개의 서로 다른 애플리케이션이 포트를 공유할 수 있습니다. 이를 통해 여러 애플리케이션이 들어오는 워크로드를 공유할 수 있습니다.`,-1),r(p,{code:``}),c[103]||=a(`h4`,{id:`여러-z-os-시스템-간-주소-공유`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#여러-z-os-시스템-간-주소-공유`},[a(`span`,null,`여러 z/OS 시스템 간 주소 공유`)])],-1),c[104]||=a(`p`,null,`여러 z/OS 시스템이 동일한 TCP/IP 주소를 공유할 수 있습니다. 외부 태스크가 이 특수 TCP/IP 주소를 지정하면, 두 z/OS 시스템 중 하나로 라우팅될 수 있습니다.`,-1),r(p,{code:``}),c[105]||=a(`h4`,{id:`고가용성-1`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#고가용성-1`},[a(`span`,null,`고가용성`)])],-1),c[106]||=a(`p`,null,`한 z/OS 시스템이 사용할 수 없으면, 외부 태스크는 다른 시스템에 연결됩니다.`,-1),r(p,{code:``}),c[107]||=n(`<h4 id="tcp-ip-공유의-특징" tabindex="-1"><a class="header-anchor" href="#tcp-ip-공유의-특징"><span>TCP/IP 공유의 특징</span></a></h4><ul><li><strong>VTAM Generic Resource와 유사</strong>: TCP/IP 포트 공유는 VTAM generic resource와 유사한 방식으로 작동</li><li><strong>고가용성</strong>: 한 시스템이 실패해도 다른 시스템이 네트워크 서비스를 계속 제공</li><li><strong>로드 밸런싱</strong>: 네트워크 트래픽을 여러 시스템 또는 애플리케이션에 분산</li><li><strong>자동 라우팅</strong>: 사용 가능한 시스템으로 자동 라우팅</li></ul><h3 id="sharing-across-sysplexes" tabindex="-1"><a class="header-anchor" href="#sharing-across-sysplexes"><span>Sharing Across Sysplexes</span></a></h3><p>지금까지 다룬 대부분의 도구와 기능은 z/OS 시스템의 태스크가 리소스를 공유할 수 있게 해주지만, 같은 sysplex 내에 있는 경우에만 가능합니다. 이러한 기능 중 어느 것도 서로 다른 sysplex 간에는 작동하지 않습니다.</p><p>서로 다른 sysplex 간에 통신하려면 일반적으로 네트워크 통신이 사용됩니다.</p><h4 id="sysplex-내에서만-공유-가능한-리소스" tabindex="-1"><a class="header-anchor" href="#sysplex-내에서만-공유-가능한-리소스"><span>Sysplex 내에서만 공유 가능한 리소스</span></a></h4><p>다음 리소스들은 같은 sysplex 내에서만 공유할 수 있습니다:</p><ul><li>VTAM generic resource</li><li>TCP/IP port and address sharing</li><li>IMS queue sharing</li><li>IMS database sharing</li><li>VSAM RLS</li><li>IBM MQ queue sharing</li><li>Db2 data sharing</li><li>Shared logstreams</li><li>Shared RACF databases</li><li>Shared enqueues</li><li>CICS sharing</li><li>XCF</li><li>Data set sharing</li><li>Tape drive sharing</li></ul>`,8),r(p,{code:``}),c[108]||=n(`<h4 id="sysplex-간-통신" tabindex="-1"><a class="header-anchor" href="#sysplex-간-통신"><span>Sysplex 간 통신</span></a></h4><p>서로 다른 sysplex 간에 통신하려면 네트워크 통신을 사용해야 합니다. 이는 표준 TCP/IP 네트워크 프로토콜을 통해 이루어집니다.</p><ul><li><strong>네트워크 통신</strong>: 서로 다른 sysplex 간 통신은 네트워크를 통해 수행</li><li><strong>격리</strong>: 각 sysplex는 독립적으로 운영되며, sysplex 내 리소스는 같은 sysplex 내에서만 공유</li><li><strong>필요 시 통신</strong>: 서로 다른 sysplex 간에 데이터를 공유하거나 통신해야 할 경우 네트워크 통신 사용</li></ul><h3 id="summary-1" tabindex="-1"><a class="header-anchor" href="#summary-1"><span>Summary</span></a></h3><p>이 섹션에서는 z/OS 서비스와 sysplex가 서로 다른 z/OS 시스템의 태스크가 리소스를 공유하고 복원력을 향상시키는 방법을 살펴봤습니다.</p>`,5),r(p,{code:``}),c[109]||=n(`<h4 id="주요-학습-내용-1" tabindex="-1"><a class="header-anchor" href="#주요-학습-내용-1"><span>주요 학습 내용</span></a></h4><ol><li><p><strong>Sysplex</strong></p><ul><li>최대 32개 z/OS 이미지를 연결하는 클러스터링 기술</li><li>채널과 coupling facility를 사용한 통신</li><li>여러 sysplex 구성 가능 (프로덕션, 개발 등)</li><li>z16 및 z17 메인프레임에서 지원</li></ul></li><li><p><strong>XCF (Cross-System Coupling Facility)</strong></p><ul><li>태스크 간 통신 제공</li><li>같은 z/OS 시스템 내 또는 다른 z/OS 시스템 간 통신</li></ul></li><li><p><strong>Time Synchronization (STP)</strong></p><ul><li>Server Time Protocol을 통한 시간 동기화</li><li>Sysplex 내 모든 시스템이 동일한 시간 유지</li></ul></li><li><p><strong>Coupling Facility</strong></p><ul><li>Parallel Sysplex의 공유 메모리</li><li>리소스 공유를 위한 핵심 구성 요소</li></ul></li><li><p><strong>Serialization (ENQ)</strong></p><ul><li>Enqueue를 통한 리소스 직렬화</li><li>QName과 RName을 사용한 리소스 제어</li><li>단일 시스템 또는 여러 시스템 간 공유</li></ul></li><li><p><strong>z/OS Sharing Facilities</strong></p><ul><li>Data sets, JES, VSAM records, Security, Logs, Tape drive 공유</li></ul></li><li><p><strong>Other Sharing Facilities</strong></p><ul><li>CICS, Db2, IMS TM, IMS DB, IBM MQ 등 미들웨어 리소스 공유</li></ul></li><li><p><strong>VTAM Logical Unit Sharing</strong></p><ul><li>VTAM generic resource를 통한 APPLID 공유</li><li>자동 라우팅 및 고가용성 제공</li><li>3270 사용자가 여러 애플리케이션에 접근</li></ul></li><li><p><strong>TCP/IP Sharing</strong></p><ul><li>TCP/IP 포트 및 주소 공유</li><li>여러 애플리케이션이 같은 포트 공유</li><li>여러 z/OS 시스템이 같은 TCP/IP 주소 공유</li><li>고가용성 및 자동 라우팅</li><li>외부 태스크가 IP 주소와 포트를 지정하여 연결</li></ul></li><li><p><strong>Sharing Across Sysplexes</strong></p><ul><li>대부분의 공유 기능은 같은 sysplex 내에서만 작동</li><li>서로 다른 sysplex 간 통신은 네트워크 통신 사용</li><li>각 sysplex는 독립적으로 운영되며 격리 유지</li></ul></li></ol><div class="hint-container tip"><p class="hint-container-title">Resource Sharing Between z/OS 요약</p><p>이 섹션에서는 z/OS 서비스와 sysplex가 서로 다른 z/OS 시스템의 태스크가 리소스를 공유하고 복원력을 향상시키는 방법을 확인했습니다.</p><ul><li><strong>3270 사용자</strong>: VTAM generic resource를 통해 여러 애플리케이션에 접근</li><li><strong>외부 태스크</strong>: TCP/IP 주소와 포트를 지정하여 z/OS 애플리케이션에 연결</li><li><strong>공유 리소스</strong>: Logs, VSAM records, Data sets, IMS TM, Db2, Security, JES, Tape drive, IMS DB, CICS, IBM MQ 등</li></ul><p>XCF, STP, coupling facility, ENQ를 기반으로 z/OS는 다양한 공유 옵션과 기능을 제공합니다. 데이터셋, 보안, 로그, 미들웨어 등 다양한 리소스가 sysplex 내에서 공유될 수 있으며, 이를 통해 고가용성, 확장성, 효율성을 달성할 수 있습니다.</p></div>`,3)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};